private val dp = Array(55) { Array(55) { LongArray(205) } }
private val c = Array(55) { LongArray(55) }

private fun min(a: Int, b: Int): Int = if (a < b) a else b
private fun max(a: Int, b: Int): Int = if (a < b) b else a

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val bufferSize = 1 shl 16
    private val buffer = ByteArray(bufferSize)
    private var len = 0
    private var ptr = 0

    private fun read(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextInt(): Int {
        var c = read()
        while (c <= 32 && c >= 0) c = read()
        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = read()
        }
        var res = 0
        while (c > 32) {
            res = res * 10 + (c - '0'.code)
            c = read()
        }
        return res * sign
    }
}

